package com.airesumebuilder.feature.job.controller;import com.airesumebuilder.common.dto.ApiResponse;import com.airesumebuilder.feature.job.service.JobService;import com.airesumebuilder.security.CurrentUser;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/jobs")public class JobController{private final JobService s;private final CurrentUser u;public JobController(JobService s,CurrentUser u){this.s=s;this.u=u;}@GetMapping("/health")public ResponseEntity<ApiResponse<String>>health(){return ResponseEntity.ok(ApiResponse.success("UP","Job matching service is available."));}@GetMapping public ResponseEntity<ApiResponse<List<JobService.Job>>>list(){return ResponseEntity.ok(ApiResponse.success(s.list(u.email()),"Jobs retrieved."));}@GetMapping("/{id}")public ResponseEntity<ApiResponse<JobService.Job>>get(@PathVariable long id){return ResponseEntity.ok(ApiResponse.success(s.get(u.email(),id),"Job retrieved."));}@PostMapping public ResponseEntity<ApiResponse<JobService.Job>>create(@Valid@RequestBody JobService.Request r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(s.create(u.email(),r),"Job created."));}@DeleteMapping("/{id}")public ResponseEntity<Void>delete(@PathVariable long id){s.delete(u.email(),id);return ResponseEntity.noContent().build();}}
